/* ── TFC Visual Animations ────────────────────────────────
 *  Micro-animations and visual candy for player view.
 *  GSAP handles imperative animations; this file provides
 *  CSS keyframes, transitions, and structural styles.
 * ──────────────────────────────────────────────────────── */

@layer components {
  /* ── A. Turn Transition Banner ──────────────────────── */

  .turn-banner {
    --banner-height: 7.5rem;
    position: relative;
    overflow: hidden;
    height: var(--banner-height);
    margin: 0 calc(-1 * var(--spacing-lg));
    perspective: 600px;
  }

  .turn-banner__layer {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    transform-origin: center bottom;
    color: var(--color-primary);
  }

  .turn-banner__layer--sky {
    opacity: 0;
    transform: translateZ(0);
  }

  .turn-banner__layer--land {
    opacity: 0;
    transform: translateY(var(--spacing-sm));
  }

  .turn-banner__layer--ship {
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transform: translateX(calc(-1 * var(--spacing-md)));
  }

  .turn-banner__layer--ship svg {
    width: var(--banner-height);
    height: auto;
    color: var(--color-foreground);
  }

  .turn-banner__label {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--color-foreground);
    opacity: 0;
    z-index: 2;
  }

  /* ── C. Decision Card Animations ────────────────────── */

  .decision-panel__option {
    transform-origin: center;
    backface-visibility: hidden;
  }

  .decision-panel__option--flipping {
    animation: card-flip var(--duration-emphasis) var(--ease-spring) forwards;
  }

