    transform: translateX(calc(-1 * var(--spacing-md)));
  }

  .turn-banner__layer--ship svg {
    width: var(--banner-height);
    height: auto;
    color: var(--color-foreground);
  }

  .turn-banner__label {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--color-foreground);
    opacity: 0;
    z-index: 2;
  }

  /* ── C. Decision Card Animations ────────────────────── */

  .decision-panel__option {
    transform-origin: center;
    backface-visibility: hidden;
  }

  .decision-panel__option--flipping {
    animation: card-flip var(--duration-emphasis) var(--ease-spring) forwards;
  }

  @keyframes card-flip {
    0% {
      transform: rotateY(0deg);
    }
    50% {
      transform: rotateY(90deg);
    }
    100% {
      transform: rotateY(0deg) scale(1.02);
    }
  }

  .decision-panel__option--submitted {
    animation: card-submit var(--duration-emphasis) var(--ease-out-expo)
      forwards;
  }

  @keyframes card-submit {
    0% {
      transform: scale(1);
      opacity: 1;
    }
    40% {
      transform: scale(1.05);
      opacity: 1;
    }
    100% {
      transform: scale(0.95) translateY(calc(-1 * var(--spacing-sm)));
      opacity: 0;
    }
  }

  /* Timer bar — GSAP controls scaleX */
  .decision-timer {
    height: var(--radius-sm);
    border-radius: var(--radius-full);
    background: var(--color-success);
    transform-origin: left;
    transition: background var(--duration-slow) var(--ease-default);
  }

  .decision-timer[data-urgency="normal"] {
    background: var(--color-success);
  }
  .decision-timer[data-urgency="warning"] {
    background: var(--color-warning);
  }
  .decision-timer[data-urgency="critical"] {
    background: var(--color-destructive);
  }

  /* ── D. Score / Stress Feedback ─────────────────────── */

  .score-bar {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-sm) var(--spacing-lg);
    background: var(--color-card);
    border-top: 1px solid var(--color-border);
    position: relative;
    overflow: hidden;
  }

  .score-bar__vignette {
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0;
    background: radial-gradient(
      ellipse at center,
      transparent 50%,
      var(--color-warning) 150%
    );
    transition: opacity var(--duration-emphasis) var(--ease-default);
  }

  .score-bar__vignette--active {
    animation: vignette-pulse var(--duration-scenic) var(--ease-default)
      forwards;
  }

  @keyframes vignette-pulse {
    0% {
      opacity: 0;
    }
    30% {
      opacity: 0.15;
    }
    100% {
      opacity: 0;
    }
  }

  .score-bar__value {
    font-family: var(--font-mono);
    font-weight: 700;
    font-size: var(--font-size-lg);
    font-variant-numeric: tabular-nums;
  }

  .score-bar__countdown {
    font-family: var(--font-mono);
    font-weight: 600;
    font-size: var(--font-size-base);
    font-variant-numeric: tabular-nums;
    color: var(--color-foreground);
  }

  .score-bar__countdown--urgent {
    color: var(--color-destructive);
    animation: countdown-blink 1s step-end infinite;
  }

  /* ── E. Ambient Background ──────────────────────────── */

  .ambient-bg {
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: -1;
    overflow: hidden;
  }

  .ambient-bg__gradient {
    position: absolute;
    inset: 0;
    background: linear-gradient(
      180deg,
      var(--color-background) 0%,
      color-mix(in oklch, var(--color-background) 95%, var(--color-primary) 5%)
        100%
    );
    animation: ambient-shift 30s ease-in-out infinite alternate;
  }

  @keyframes ambient-shift {
    0% {
      opacity: 1;
    }
    100% {
      opacity: 0.6;
    }
  }

  .ambient-bg__waves {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 200%;
    height: var(--spacing-2xl);
    color: var(--color-primary);
    animation: wave-drift 20s linear infinite;
  }

  @keyframes wave-drift {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  .ambient-bg__fog {
    position: absolute;
    inset: 0;
    background: var(--color-background);
    opacity: 0;
    transition: opacity 2s var(--ease-default);
  }

  .ambient-bg__fog--active {
    opacity: 0.15;
  }

  /* ── F. Advisor Recommendation Bubbles ──────────────── */

  .advisor-bubble {
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--radius-full);
    background: var(--color-secondary);
    border: 1px solid var(--color-border);
    font-size: var(--font-size-xs);
    opacity: 0;
    transform: scale(0.8) translateY(var(--spacing-sm));
  }

  .advisor-bubble__avatar {
    --avatar-size: 1.25rem;
    width: var(--avatar-size);
    height: var(--avatar-size);
    border-radius: var(--radius-full);
    background: var(--color-primary);
    color: var(--color-primary-foreground);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--font-size-xs);
    font-weight: 700;
  }

  .advisor-bubble__count {
    --count-size: 1.125rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--count-size);
    height: var(--count-size);
    border-radius: var(--radius-full);
    background: var(--color-primary);
    color: var(--color-primary-foreground);
    font-size: var(--font-size-xs);
    font-weight: 700;
    font-variant-numeric: tabular-nums;
  }

  .advisor-bubble__count--bounce {
    animation: count-bounce var(--duration-slow) var(--ease-spring);
  }

  @keyframes count-bounce {
    0% {
      transform: scale(1);
    }
    40% {
      transform: scale(1.3);
    }
    100% {
      transform: scale(1);
    }
  }

  /* ── Reduced Motion ─────────────────────────────────── */

  @media (prefers-reduced-motion: reduce) {
    .turn-banner,
    .ambient-bg__waves,
    .ambient-bg__gradient {
      animation: none;
    }

    .decision-panel__option--flipping,
    .decision-panel__option--submitted,
    .score-bar__vignette--active,
    .advisor-bubble__count--bounce {
      animation: none;
    }
  }
}

