test.describe("Combined state — all invariants hold together @player", () => {
  test("advisor with score, events, issues, and open decision", async ({
    page,
  }) => {
    await installMocks(
      page,
      snapshot({
        phase: "running",
        score: SCORE_TURN_3,
        events: [EVENT_RUNNING, EVENT_COMPLETED, EVENT_SCHEDULED],
