      } else if (state.phase === "briefing") {
        // Briefing shows "Turn 0" banner
        await expect(banner).toBeVisible();
        await expect(banner).toContainText("Turn 0");
      } else {
        await expect(banner).not.toBeVisible();
      }
    }),
    { numRuns: NUM_RUNS },
  );
});

